function renderLabel(value,lang){const raw=value.trim();if(viNames[raw])value=value.replace(raw,viNames[raw]);if(lang!=='en')return value;const key=value.trim();if(pairs[key])return value.replace(key,pairs[key]);let out=value;for(const [vi,en]of prefixPairs){if(vi.length<5)continue;if(out.startsWith(vi+' ')||out.startsWith(vi+':')||out.startsWith(vi+' ·')||out.startsWith(vi+' (')){out=en+out.slice(vi.length);break}}return out.replace(/(\d+) tập/g,'$1 episodes').replace(/(\d+) cảnh/g,'$1 scenes').replace(/(\d+) giây/g,'$1 seconds').replace(/(\d+) ảnh/g,'$1 images').replace(/Ảnh (\d+)/g,'Image $1').replace(/Vùng (\d+)/g,'Region $1').replace(/Tài khoản (\d+)/g,'Account $1').replace(/(\d+) tổng/g,'$1 total').replace(/Đang xử lý/g,'Processing').replace(/Đang chờ/g,'Queued').replace(/Hoàn tất/g,'Completed').replace(/Đã dừng/g,'Stopped');}
const translateLabel=renderLabel;renderLabel=function(value,lang){const key=lang+'|'+value;if(labelCache.has(key))return labelCache.get(key);const result=translateLabel(value,lang);if(labelCache.size>10000)labelCache.clear();labelCache.set(key,result);return result};
export function mountLanguage(){let lang=localStorage.getItem('muse-language')||'vi';const originals=new WeakMap(),attrs=new WeakMap();let queued=false;const ignored=n=>n.parentElement?.closest('input,textarea,[contenteditable=true],pre,code,.muse-prompt-proposal,.prompt-library-grid article>p,.muse-viewer-info pre,.sx-prompt');function translate(){queued=false;const root=document.getElementById('root');if(!root)return;document.documentElement.lang=lang;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){if(ignored(n))continue;const old=originals.get(n);if(!old||n.nodeValue!==old.output){originals.set(n,{source:n.nodeValue,output:n.nodeValue})}const item=originals.get(n),trim=item.source.trim(),value=renderLabel(item.source,lang);if(n.nodeValue!==value)n.nodeValue=value;item.output=value}root.querySelectorAll('button:has(svg),a:has(svg)').forEach(el=>{if(!el.title){const label=el.getAttribute('aria-label')||el.textContent.trim();if(label)el.title=label}});root.querySelectorAll('[title],[aria-label],[placeholder]').forEach(el=>{if(el.closest('[contenteditable=true]'))return;let values=attrs.get(el);if(!values){values={};attrs.set(el,values)}for(const key of ['title','aria-label','placeholder']){const value=el.getAttribute(key);if(value===null)continue;if(!values[key]||value!==values[key].output)values[key]={source:value,output:value};const entry=values[key],next=renderLabel(entry.source,lang);if(next!==value)el.setAttribute(key,next);entry.output=next}});const btn=document.getElementById('muse-language-toggle');if(btn)btn.textContent=lang==='vi'?'VI / EN':'EN / VI';window.museTranslateLabel=value=>renderLabel(value,lang)}const observer=new MutationObserver(()=>{if(!queued){queued=true;requestAnimationFrame(translate)}});observer.observe(document.getElementById('root'),{subtree:true,childList:true,characterData:true});const btn=document.createElement('button');btn.id='muse-language-toggle';btn.title='Đổi ngôn ngữ / Switch language';btn.addEventListener('click',()=>{lang=lang==='vi'?'en':'vi';localStorage.setItem('muse-language',lang);translate()});document.body.appendChild(btn);translate();return()=>{observer.disconnect();btn.remove()}}
